            vert = c
            break
    # find the other object (non-2, non-background) cells
    # background = most common color that isn't 2 or 8
    from collections import Counter
    cnt = Counter()
    for r in range(h):
        for c in range(w):
            cnt[grid[r][c]] += 1
    bg = None
    for col, n in cnt.most_common():
        if col not in (2, 8):
            bg = col
            break
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2]
    if not cells:
