    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    height = r1 - r0 + 1
    width = c1 - c0 + 1
    sub = [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
    out = [[bg] * w for _ in range(h)]
    # redraw the 2 line
    if horiz is not None:
