        nc0 = c0
        # draw 8 line on the far side, full width
        if nr0 + height - 1 < h - 1 and nr0 > horiz:
            line = nr0 + height
        else:
            line = nr0 - 1
        for c in range(w):
            out[line][c] = 8
        for i in range(height):
            for j in range(width):
                out[nr0 + i][nc0 + j] = sub[i][j]
    elif vert is not None:
        if c0 > vert:
            nc0 = vert + 1
        else:
            nc0 = vert - width
        nr0 = r0
        if nc0 + width - 1 < w - 1 and nc0 > vert:
            line = nc0 + width
        else:
            line = nc0 - 1
        for r in range(h):
            out[r][line] = 8
        for i in range(height):
            for j in range(width):
                out[nr0 + i][nc0 + j] = sub[i][j]
    return out
